1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 目录内两份或更多记录文件顶层保存相同作业号（文件名不同、乃至内容
76	//     完全相同）时打开失败，返回非空错误且归档对象为 nil；错误说明重复的
77	//     作业号与冲突文件名。此时不启动任何计算，也不改写目录内任何原有
78	//     记录，调用方处理冲突后再次打开才按下列规则恢复；
79	//   - 两份作业号不同的记录保存了相同提交人与同一个非空请求号时同样打开
80	//     失败，返回非空错误且归档对象为 nil；错误说明重复归属的请求号、提交
81	//     人、两个冲突作业号与各自文件名。标识按恢复后的完整字节比较（含
82	//     U+0000 与非法 UTF-8）；空请求号不启用幂等故不参与，不同提交人使用
83	//     相同请求号合法。即使两份记录内容完全相同、或其中一份已失败/取消也
84	//     不合并、不释放请求号；同样不启动计算、不改写任何原有记录；
85	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
86	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
87	//   - 成功状态始终与完整归档同时可见。
88	func Open(dir string, opts ...Option) (*Store, error) {
89		if err := os.MkdirAll(dir, 0o700); err != nil {
90			return nil, err
91		}
92		jobs, maxID, err := loadDir(dir)
93		if err != nil {
94			return nil, err
95		}
96		s := &Store{
97			dir:    dir,
98			jobs:   jobs,
99			byID:   make(map[uint64]*storedJob),
100			idem:   make(map[idemIdentity]uint64),
101			nextID: maxID + 1,
102			now:    wallClock{}.Now,
103			waitCh: make(chan struct{}, 1),
104			stopCh: make(chan struct{}),
105		}
106		for _, opt := range opts {
107			opt(s)
108		}
109		for _, j := range jobs {
110			s.byID[j.id] = j
111			if j.requestID != "" {
112				// loadDir 已在任何恢复改写之前确认同一提交人的非空请求号不会跨
113				// 不同作业号重复，因此这里的索引恢复与提交路径遵守同一项唯一性。
114				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
115			}
116		}
117		// 重建失败/取消作业对排队下游的阻断。
118		s.cascadeLocked()
119		s.wg.Add(1)
120		go s.worker()
121		return s, nil
122	}
123	
124	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
125	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
126	//
127	// 多次 Close（含并发调用）共同完成对同一个归档对象的一次关闭：每个调用都
128	// 等到 worker 退出、运行中作业的中断处理已经落盘后才成功返回。后发调用
129	// 不能只因为前一次调用已把关闭标记置位就提前返回——否则调用方可能据此立即
130	// 重新打开目录，而旧 worker 仍在补写运行作业的结果。归档完全关闭后的再次
131	// Close 立即成功返回；空闲归档（无运行中作业）也直接完成关闭。
132	func (s *Store) Close() error {
133		s.mu.Lock()
134		if s.closed {
135			// 关闭可能正由另一次并发 Close 进行。wg 在 Open 时 +1、worker 退出
136			// 时归零；Wait 允许被多个 goroutine 同时等待，所有调用都在同一次
137			// 关闭真正完成（worker 已退出、再无计算与补写）时才返回。
138			// 已完全关闭时计数早已归零，这里立即成功返回。
139			s.mu.Unlock()
140			s.wg.Wait()
141			return nil
142		}
143		s.closed = true
144		// 停止标记必须与 closed 在同一次持锁中生效：Submit 的拒绝、worker 的
145		// “是否从队列启动新计算”与“是否把刚结束的计算确认为成功”都观察同一把
146		// 锁。若先放开锁再置 stopping，worker 可能在这个窗口内通过循环开头的
147		// 检查并启动排队作业，或把尚未确认保存的计算按成功落盘——调用方已经在
148		// 被 ErrStoreClosed 拒绝，却仍能拿到关闭过程新产生的成功结果。
149		if s.stopping.CompareAndSwap(false, true) {
150			close(s.stopCh)
151		}
152		var running *storedJob
153		if s.runningID != 0 {
154			running = s.byID[s.runningID]
155		}
156		s.mu.Unlock()
157	
158		// 中止正在运行的计算。
159		if running != nil {
160			running.canceled.Store(true)
161		}
162		s.notify()
163		s.wg.Wait()
164		return nil
165	}
166	
167	// Submit 接受一次作业提交。
168	//
169	// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
170	// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
171	// 幂等判定拒绝，即使复用已接受的请求号也不例外。
172	//
173	// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
174	// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
175	// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
176	// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
177	// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
178	// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
179	//
180	// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
181	// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
182	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
183	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
184		s.mu.Lock()
185		defer s.mu.Unlock()
186		if s.closed || s.stopping.Load() {
187			return nil, ErrStoreClosed
188		}
189		if len(req.Values) == 0 {
190			return nil, ErrEmptySequence
191		}
192		// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
193		// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
194		if err := s.validateDependencyShapeLocked(&req); err != nil {
195			return nil, err
196		}
197		deps := requestDeps(&req)
198		if req.RequestID != "" {
199			key := idemIdentity{req.Submitter, req.RequestID}
200			if origID, ok := s.idem[key]; ok {
201				orig := s.byID[origID]
202				// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
203				// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
204				// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
205				// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
206				// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
207				if sameContent(orig, &req) {
208					return s.viewLocked(orig), nil
209				}
210				return s.viewLocked(orig),
211					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
212						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
213						s.missingDependencyNoteLocked(deps))
214			}
215		}
216		// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
217		// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
218		// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
219		if err := s.validateDependenciesExistLocked(deps); err != nil {
220			return nil, err
221		}
222	
223		now := s.now().UTC()
224		j := &storedJob{
225			id:           s.nextID,
226			submitter:    req.Submitter,
227			requestID:    req.RequestID,
228			seed:         req.Seed,
229			values:       append([]int64(nil), req.Values...),
230			dependencies: append([]uint64(nil), deps...),
231			queuedAt:     now,
232			status:       StatusQueued,
233		}
234		// 先持久化，接受之后该提交即不可丢失。
235		if err := s.persist(j); err != nil {
236			return nil, err
237		}
238		s.nextID++
239		s.jobs = append(s.jobs, j)
240		s.byID[j.id] = j
241		if req.RequestID != "" {
242			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
243		}
244		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
245		s.cascadeLocked()
246		s.notifyLocked()
247		return s.viewLocked(j), nil
248	}
249	
250	// requestDeps 规范化一次提交的直接上游作业号列表，与记录、归档共用 deps.go
251	// 中的同一换算：非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含
252	// 一个作业号的列表；两者皆无则为 nil。调用前须先经
253	// [Store.validateDependencyShapeLocked] 与（新请求路径上的）
254	// [Store.validateDependenciesExistLocked] 校验。
255	func requestDeps(req *SubmitRequest) []uint64 {
256		return normalizeDependencies(req.HasDependency, req.DependencyID, req.Dependencies)
257	}
258	
259	// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
260	// 无关的结构问题：
261	//   - 单依赖方式与非空列表同时启用 → 拒绝；
262	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
263	//
264	// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
265	// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
266	// 也仍返回原有的对应拒绝。
267	func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
268		if req.HasDependency && len(req.Dependencies) > 0 {
269			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
270		}
271		deps := requestDeps(req)
272		seen := make(map[uint64]struct{}, len(deps))
273		for _, id := range deps {
274			if id == 0 {
275				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
276			}
277			if _, dup := seen[id]; dup {
278				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
279			}
280			seen[id] = struct{}{}
281		}
282		return nil
283	}
284	
285	// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
286	// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
287	// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
288	//
289	// 任一拒绝都不产生记录，也不占用幂等请求号。
290	func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
291		for _, id := range deps {
292			if s.byID[id] == nil {
293				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
294			}
295		}
296		return nil
297	}
298	
299	// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
300	// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
301	// 不会被误读成仅仅是上游不存在。
302	func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
303		for _, id := range deps {
304			if s.byID[id] == nil {
305				return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
306			}
307		}
308		return ""
309	}
310	
311	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
312	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
313	func sameContent(j *storedJob, req *SubmitRequest) bool {
314		if j.seed != req.Seed {
315			return false
316		}
317		rd := requestDeps(req)
318		if len(j.dependencies) != len(rd) {
319			return false
320		}
321		for i := range j.dependencies {
322			if j.dependencies[i] != rd[i] {
323				return false
324			}
325		}
326		if len(j.values) != len(req.Values) {
327			return false
328		}
329		for i := range j.values {
330			if j.values[i] != req.Values[i] {
331				return false
332			}
333		}
334		return true
335	}
336	
337	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
338	func (s *Store) Get(id uint64) (*Job, error) {
339		s.mu.Lock()
340		defer s.mu.Unlock()
341		j := s.byID[id]
342		if j == nil {
343			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
344		}
345		return s.viewLocked(j), nil
346	}
347	
348	// Cancel 请求取消作业。
349	//
350	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
351	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
352	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
353	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
354	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
355	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
356	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
357	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
358	func (s *Store) Cancel(id uint64) (*Job, error) {
359		s.mu.Lock()
360		defer s.mu.Unlock()
361		if s.closed {
362			return nil, ErrStoreClosed
363		}
364		j := s.byID[id]
365		if j == nil {
366			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
367		}
368		switch j.status {
369		case StatusCanceled:
370			return s.viewLocked(j), nil
371		case StatusSucceeded, StatusFailed:
372			return s.viewLocked(j),
373				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
374		}
375	
376		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
377		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
378		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
379		// 不能把这次取消当作已完成。
380		now := s.now().UTC()
381		prevStatus := j.status
382		prevFinishedAt := j.finishedAt
383		prevReason := j.failureReason
384		prevBlocker := j.blockerID
385		prevEffective := j.effectiveValues
386		prevArchive := j.archive
387		j.status = StatusCanceled
388		j.failureReason = ""
389		j.blockerID = 0
390		if j.finishedAt.IsZero() {
391			j.finishedAt = now
392		}
393		j.effectiveValues = nil
394		j.archive = nil
395		if err := s.persist(j); err != nil {
396			j.status = prevStatus
397			j.finishedAt = prevFinishedAt
398			j.failureReason = prevReason
399			j.blockerID = prevBlocker
400			j.effectiveValues = prevEffective
401			j.archive = prevArchive
402			return nil, err
403		}
404	
405		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
406		j.canceled.Store(true)
407		// 依赖它的等待者一并失败，且继续向更下游传播。
408		s.cascadeLocked()
409		s.notifyLocked()
410		return s.viewLocked(j), nil
411	}
412	
413	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
414	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
415	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
416		s.mu.Lock()
417		defer s.mu.Unlock()
418		if !start.IsZero() && !end.IsZero() && start.After(end) {
419			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
420				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
421		}
422		out := make([]*Job, 0)
423		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
424			if j.submitter != submitter {
425				continue
426			}
427			if !start.IsZero() && j.queuedAt.Before(start) {
428				continue
429			}
430			if !end.IsZero() && j.queuedAt.After(end) {
431				continue
432			}
433			out = append(out, s.viewLocked(j))
434		}
435		return out, nil
436	}
437	
438	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
439	//
440	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
441	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
442	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
443	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
444	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
445	func (s *Store) cascadeLocked() {
446		for _, j := range s.jobs {
447			if j.status != StatusQueued || len(j.dependencies) == 0 {
448				continue
449			}
450			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
451			if !blocked {
452				continue
453			}
454			root := blockerRoot(direct, directID)
455			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
456		}
457	}
458	
459	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
460	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
461	// 该作业就被跳过，不挡住后面可运行的作业。
462	func (s *Store) pickRunnableLocked() *storedJob {
463		for _, j := range s.jobs {
464			if j.status != StatusQueued {
465				continue
466			}
467			if len(j.dependencies) == 0 {
468				return j
469			}
470			ready := true
471			for _, id := range j.dependencies {
472				dep := s.byID[id]
473				if dep == nil || dep.status != StatusSucceeded {
474					ready = false
475					break
476				}
477			}
478			if ready {
479				return j
480			}
481		}
482		return nil
483	}
484	
485	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
486	func (s *Store) notifyLocked() {
487		select {
488		case s.waitCh <- struct{}{}:
489		default:
490		}
491	}
492	
493	// notify 在不持锁时唤醒 worker。
494	func (s *Store) notify() {
495		s.mu.Lock()
496		s.notifyLocked()
497		s.mu.Unlock()
498	}
499	
500	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
501	func (s *Store) persistRetry(j *storedJob, attempts int) error {
502		var err error
503		for i := 0; i < attempts; i++ {
504			if err = s.persist(j); err == nil {
505				return nil
506			}
507		}
508		return err
509	}
510	
511	// worker 是本地唯一的计算执行体。
512	func (s *Store) worker() {
513		defer s.wg.Done()
514		for {
515			s.mu.Lock()
516			if s.stopping.Load() {
517				s.mu.Unlock()
518				return
519			}
520			j := s.pickRunnableLocked()
521			if j == nil {
522				ch := s.waitCh
523				s.mu.Unlock()
524				select {
525				case <-ch:
526				case <-s.stopCh:
527				}
528				continue
529			}
530	
531			// 进入运行并原子持久化该状态。
532			j.status = StatusRunning
533			j.startedAt = s.now().UTC()
534			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
535			inputs := append([]int64(nil), j.values...)
536			for _, id := range j.dependencies {
537				if dep := s.byID[id]; dep != nil && dep.archive != nil {
538					inputs = append(inputs, dep.archive.Sum)
539				}
540			}
541			seed := j.seed
542			s.runningID = j.id
543			if err := s.persistRetry(j, 3); err != nil {
544				// 连运行状态都无法落盘：保守地失败，不进行计算。
545				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
546				s.runningID = 0
547				s.cascadeLocked()
548				s.notifyLocked()
549				s.mu.Unlock()
550				continue
551			}
552			s.mu.Unlock()
553	
554			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
555			doCompute := s.compute
556			if doCompute == nil {
557				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
558					return computeResult(in, sd, c)
559				}
560			}
561			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
562	
563			s.mu.Lock()
564			s.runningID = 0
565			switch {
566			case j.status == StatusCanceled:
567				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
568				j.archive = nil
569				j.effectiveValues = nil
570				_ = s.persistRetry(j, 3)
571				s.cascadeLocked()
572			case s.stopping.Load():
573				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
574				s.cascadeLocked()
575			case !ok:
576				s.markFailedLocked(j, reason, 0)
577				s.cascadeLocked()
578			default:
579				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
580				completed := s.now().UTC()
581				a := newArchive(j, inputs, sum, sumSq, completed)
582				j.effectiveValues = append([]int64(nil), inputs...)
583				j.status = StatusSucceeded
584				j.finishedAt = completed
585				j.failureReason = ""
586				j.blockerID = 0
587				j.archive = a
588				if err := s.persistRetry(j, 3); err != nil {
589					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
590					j.archive = nil
591					j.effectiveValues = nil
592					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
593					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
594					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
595					s.cascadeLocked()
596				}
597			}
598			s.notifyLocked()
599			s.mu.Unlock()
600		}
601	}
602	
603	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
604	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
605		j.status = StatusFailed
606		j.failureReason = reason
607		j.blockerID = blocker
608		if j.finishedAt.IsZero() {
609			j.finishedAt = s.now().UTC()
610		}
611		j.archive = nil
612		j.effectiveValues = nil
613		_ = s.persistRetry(j, 3)
614	}
615	
616	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
617	// 上游作业号只作记录，不参与任何摘要与校验值。
618	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
619		inDigest := inputsDigestHex(effective, j.seed)
620		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
621		log := buildLog(effective, j.seed, sum, sumSquares)
622		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
623		hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
624		return &Archive{
625			JobID:           j.id,
626			Submitter:       j.submitter,
627			RequestID:       j.requestID,
628			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
629			Seed:            j.seed,
630			Values:          append([]int64(nil), j.values...),
631			HasDependency:   hasDependency,
632			DependencyID:    dependencyID,
633			Dependencies:    append([]uint64(nil), j.dependencies...),
634			EffectiveValues: append([]int64(nil), effective...),
635			InputsDigest:    inDigest,
636			Sum:             sum,
637			SumOfSquares:    sumSquares,
638			ResultDigest:    resDigest,
639			Log:             log,
640			Checksum:        checksum,
641			CompletedAt:     completedAt,
642		}
643	}
644	
645	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
646	func (s *Store) viewLocked(j *storedJob) *Job {
647		v := &Job{
648			ID:              j.id,
649			Submitter:       j.submitter,
650			RequestID:       j.requestID,
651			Seed:            j.seed,
652			Values:          append([]int64(nil), j.values...),
653			Dependencies:    append([]uint64(nil), j.dependencies...),
654			QueuedAt:        j.queuedAt,
655			StartedAt:       j.startedAt,
656			FinishedAt:      j.finishedAt,
657			Status:          j.status,
658			FailureReason:   j.failureReason,
659			BlockerID:       j.blockerID,
660			EffectiveValues: append([]int64(nil), j.effectiveValues...),
661		}
662		v.HasDependency, v.DependencyID = legacyDependencyFields(j.dependencies)
663		if j.status == StatusQueued {
664			v.WaitReason = WaitSlot
665			// 列出尚未成功归档的直接上游，保持提交时的顺序。
666			for _, id := range j.dependencies {
667				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
668					v.PendingDependencies = append(v.PendingDependencies, id)
669				}
670			}
671			if len(v.PendingDependencies) > 0 {
672				v.WaitReason = WaitDependency
673			}
674		}
675		if j.archive != nil {
676			a := *j.archive
677			a.Values = append([]int64(nil), j.archive.Values...)
678			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
679			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
680			if j.archive.IdentityRaw != nil {
681				raw := *j.archive.IdentityRaw
682				a.IdentityRaw = &raw
683			}
684			v.Archive = &a
685		}
686		return v
687	}
688	
689	// Dir 返回归档目录路径。
690	func (s *Store) Dir() string { return s.dir }
691

