1	package numeric
2	
3	import (
4		"errors"
5		"io/fs"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// makeArchiveReadOnly 把归档目录临时变为目录本身不可写（无法创建临时文件、
13	// 无法 rename 替换记录），并在测试结束时自动恢复，避免污染 t.TempDir 的清理。
14	// 若当前权限模型下只读目录仍可写（例如以 root 运行），故障注入无法成立，
15	// 跳过测试而不是误报失败。
16	func makeArchiveReadOnly(t *testing.T, dir string) {
17		t.Helper()
18		if err := os.Chmod(dir, 0o500); err != nil {
19			t.Fatalf("chmod 0500: %v", err)
20		}
21		t.Cleanup(func() { _ = os.Chmod(dir, 0o700) })
22		probe := filepath.Join(dir, ".tmp-write-probe")
23		if err := os.WriteFile(probe, []byte("x"), 0o600); err == nil {
24			_ = os.Remove(probe)
25			_ = os.Chmod(dir, 0o700)
26			t.Skip("只读目录在当前环境下仍可写，无法注入保存失败（通常为 root 运行）")
27		}
28	}
29	
30	func makeArchiveWritable(t *testing.T, dir string) {
31		t.Helper()
32		if err := os.Chmod(dir, 0o700); err != nil {
33			t.Fatalf("chmod 0700: %v", err)
34		}
35	}
36	
37	// 排队作业取消时无法保存：返回实际保存错误，作业在内存与磁盘上都保持排队，
38	// 不新增完成时间、不清空信息、不级联下游；写入恢复后重新取消才生效，
39	// 重新打开归档仍保留这次已确认的取消，且作业号与提交参数不变。
40	func TestCancelQueuedPersistFailureKeepsStateAndRetries(t *testing.T) {
41		dir := t.TempDir()
42		s, err := Open(dir, WithClock(newManualClock()))
43		if err != nil {
44			t.Fatal(err)
45		}
46		started, block, release, _, _ := gateCompute(t, s)
47		block(1)
48	
49		head := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
50		waitStarted(t, started, head.ID)
51		q := mustSubmit(t, s, SubmitRequest{
52			Submitter: "a", RequestID: "cq", Values: []int64{5}, Seed: 7,
53		})
54		child := mustSubmit(t, s, SubmitRequest{
55			Submitter: "a", Values: []int64{9},
56			HasDependency: true, DependencyID: q.ID,
57		})
58	
59		onDisk := func() string {
60			data, err := os.ReadFile(filepath.Join(dir, jobFileName(q.ID)))
61			if err != nil {
62				t.Fatal(err)
63			}
64			return string(data)
65		}
66		if !strings.Contains(onDisk(), `"status": "queued"`) {
67			t.Fatal("queued job not persisted as queued before cancel")
68		}
69	
70		// 目录暂时不可写：取消必须返回底层错误，不能返回任何成功视图。
71		makeArchiveReadOnly(t, dir)
72		if cj, err := s.Cancel(q.ID); err == nil {
73			t.Fatalf("cancel with unwritable dir returned success: %+v", cj)
74		} else if !errors.Is(err, fs.ErrPermission) {
