76		}
77		// 首次未保存的取消不能被当成已完成操作：紧接着的重复请求同样失败。
78		if _, err := s.Cancel(q.ID); !errors.Is(err, fs.ErrPermission) {
79			t.Fatalf("repeat cancel while unwritable err=%v, want permission error", err)
80		}
81	
82		// 内存可查询状态保持原状态：仍排队、无完成时间、保留参数、等待计算位置。
83		g, _ := s.Get(q.ID)
84		if g.Status != StatusQueued || !g.FinishedAt.IsZero() || g.WaitReason != WaitSlot {
85			t.Fatalf("job changed after failed cancel: status=%s finished=%s reason=%q",
86				g.Status, g.FinishedAt, g.WaitReason)
87		}
88		if g.ID != q.ID || g.Submitter != "a" || g.RequestID != "cq" ||
89			g.Seed != 7 || len(g.Values) != 1 || g.Values[0] != 5 {
90			t.Fatalf("submit params altered after failed cancel: %+v", g)
91		}
92		// 运行中的作业未被提前中止，等待依赖的下游也没有仅因这次请求被标记失败。
93		if h, _ := s.Get(head.ID); h.Status != StatusRunning || !h.FinishedAt.IsZero() {
94			t.Fatalf("running job disturbed by failed cancel: %+v", h)
95		}
96		c, _ := s.Get(child.ID)
97		if c.Status != StatusQueued || c.WaitReason != WaitDependency || !c.FinishedAt.IsZero() {
98			t.Fatalf("downstream disturbed by failed cancel: %+v", c)
99		}
100		// 磁盘上仍是原来的排队记录。
101		if !strings.Contains(onDisk(), `"status": "queued"`) ||
102			strings.Contains(onDisk(), `"status": "canceled"`) {
103			t.Fatalf("disk record changed despite failed cancel:\n%s", onDisk())
104		}
105	
106		// 写入恢复：对仍排队的同一作业重新取消，成功后才返回取消状态。
107		makeArchiveWritable(t, dir)
108		cj, err := s.Cancel(q.ID)
