114			t.Fatalf("confirmed cancel must keep job id and submit params: %+v", cj)
115		}
116		// 已成功保存的取消允许重复请求返回成功。
117		if again, err := s.Cancel(q.ID); err != nil || again.Status != StatusCanceled {
118			t.Fatalf("repeat confirmed cancel: %+v %v", again, err)
119		}
120		// 直到取消确认后，依赖它的下游才按现有规则失败并指出阻断作业。
121		fc := waitStatus(t, s, child.ID, StatusFailed)
122		if fc.BlockerID != q.ID || !strings.Contains(fc.FailureReason, "取消") {
123			t.Fatalf("downstream failure after confirmed cancel: %+v", fc)
124		}
125	
126		release(head.ID)
127		waitStatus(t, s, head.ID, StatusSucceeded)
128		if err := s.Close(); err != nil {
129			t.Fatal(err)
130		}
131	
132		// 重新打开同一归档：已确认的取消与下游失败都保留。
133		s2, err := Open(dir)
134		if err != nil {
135			t.Fatal(err)
136		}
