196		big := int64(3037000500)
197		bad := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{big}})
198		waitStarted(t, started, bad.ID)
199		makeArchiveReadOnly(t, s.Dir())
200		if _, err := s.Cancel(bad.ID); !errors.Is(err, fs.ErrPermission) {
201			t.Fatalf("cancel overflow job while unwritable: %v", err)
202		}
203		makeArchiveWritable(t, s.Dir())
204		release(bad.ID)
205		failed := waitStatus(t, s, bad.ID, StatusFailed)
206		if !strings.Contains(failed.FailureReason, "平方和") || failed.Archive != nil {
