213			g.FailureReason != failed.FailureReason || g.Archive != nil {
214			t.Fatalf("failed result changed after rejected cancel: %+v", g)
215		}
216	}
217	
218	// 排队作业取消保存失败本身不改变调度：恢复写入但不重新取消、放行前面的作业后，
219	// 该作业仍按原有排队规则正常计算并成功。
220	func TestFailedQueuedCancelDoesNotChangeScheduling(t *testing.T) {
221		s, _ := openTestStore(t)
222		started, block, release, _, _ := gateCompute(t, s)
