241		}
242	}
243	
244	// 取消成功保存后，正在运行的计算即使随后“成功完成”也不能留下成功归档；
245	// 关闭重开归档后，已确认的取消仍然成立。
246	func TestConfirmedRunningCancelDiscardsLateSuccess(t *testing.T) {
247		dir := t.TempDir()
248		s, err := Open(dir)
249		if err != nil {
