287		s2, err := Open(dir)
288		if err != nil {
289			t.Fatal(err)
290		}
291		defer s2.Close()
292		g, _ := s2.Get(run.ID)
293		if g.Status != StatusCanceled || g.Archive != nil {
294			t.Fatalf("confirmed running cancel after reopen: %+v", g)
295		}
296	}
