28	func openTestStore(t *testing.T) (*Store, *manualClock) {
29		t.Helper()
30		clock := newManualClock()
31		s, err := Open(t.TempDir(), WithClock(clock))
32		if err != nil {
33			t.Fatalf("open: %v", err)
34		}
35		t.Cleanup(func() { _ = s.Close() })
36		return s, clock
