}

func TestOverflowFailureLeavesNoSuccess(t *testing.T) {
	s, _ := openTestStore(t)
	big := int64(3037000500)
	j := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{big, 1, 2}})
	failed := waitStatus(t, s, j.ID, StatusFailed)
