	if err != nil {
		t.Fatal(err)
	}
	if g2.Status != StatusFailed || g2.Archive != nil || len(g2.EffectiveValues) != 0 {
		t.Fatalf("重开后应读到失败状态且无归档与实际输入：%+v", g2)
