	// 运行与完成都写回原文件：目录中只有 custom 这一份作业 q 的记录。
	assertNoDefaultRecord(t, dir, q.ID)
	data, err := os.ReadFile(filepath.Join(dir, custom))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(data), `"status": "succeeded"`) {
		t.Fatalf("成功状态必须写回原记录文件：\n%s", data)
