// 目录中始终只有那一份正式记录；关闭再开读取到更新后的成功状态与完整归档，
// 其他作业的记录不被移动或重写。
func TestRestoredQueuedJobWithSuffixedFileNameUpdatesSameFile(t *testing.T) {
