	// 作业号由记录内容识别，这不是第二份作业。
	custom := suffixedRecordName(q.ID)
	if err := os.Rename(filepath.Join(dir, jobFileName(q.ID)), filepath.Join(dir, custom)); err != nil {
		t.Fatal(err)
	}
