	headAfter, err := os.ReadFile(filepath.Join(dir, jobFileName(head.ID)))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(headBefore, headAfter) {
		t.Fatal("其他作业的记录不应被重写")
	}
	if err := s2.Close(); err != nil {
		t.Fatal(err)
	}

	// 再次打开：系统没有制造同号副本，打开成功并读到更新后的完整归档。
	s3, err := Open(dir)
	if err != nil {
